\begin{itemchoice}
			\itemch Sai. Hàm số có tập xác định là $\mathcal{D} = [0;32]$.
			\itemch Đúng. Ta có $f'(x) = \displaystyle\frac{1}{2\sqrt{x}} - \displaystyle\frac{1}{2\sqrt{32-x}}$.
			\itemch Sai. Ta có $f'(x)=0 \Leftrightarrow \sqrt{32-x} = \sqrt{x} \Leftrightarrow x=16$.
			\itemch Đúng. Bảng biến thiên
			\begin{center}
				<img src='HinhAnh/sol_478165957c_lg_tikz_1.png' style='max-width: 100%; height: auto; display: block; margin: 10px auto;' />
			\end{center}
			Từ bảng biến thiên, ta có $\max\limits_{x \in \mathcal{D}} f(x) = 8, \min\limits_{x \in \mathcal{D}} f(x) = 4\sqrt{2}$. Vậy $\displaystyle\frac{m}{M} = \displaystyle\frac{4\sqrt{2}}{8} = \displaystyle\frac{\sqrt{2}}{2}$.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có: $f\left(\displaystyle\frac{1}{e^2}\right) = \displaystyle\frac{1}{e^2} \ln\left(e^{-2}\right) = -\frac{2}{e^2}$. Và $f(e) = e \ln e = e$.
			\itemch Ta có: $f'(x) = (x \ln x)' = \ln x + x \cdot \displaystyle\frac{1}{x} = \ln x + 1$.
			\itemch Ta có $f'(x) = 0 \Leftrightarrow \ln x + 1 = 0 \Leftrightarrow x = \displaystyle\frac{1}{e} \in \left[e^{-2}; e\right]$.
			\itemch Ta có: $f(e^{-2}) = -\displaystyle\frac{2}{e^2}$; $f(e^{-1}) = -\displaystyle\frac{1}{e}$; $f(e) = e$.\\ Vậy giá trị nhỏ nhất của $f(x)$ trên đoạn $\left[e^{-2}; e\right]$ là $-\displaystyle\frac{1}{e}$.
		\end{itemchoice}
